"""One delivery contract for initial generation, followers and manual regeneration."""
ROLES=(
 ('01_main','主图：准确展示本变体真实颜色、规格及销售数量；醒目的俄语大标题，旁边清晰罗列2—4条有事实依据的重要卖点，文字简洁、层级清晰、不遮挡商品'),
 ('02_dimensions','商品尺寸图：只采用商品尺寸，不能把包装尺寸写成商品尺寸；全组尺寸不同时明确标注对应选项'),
 ('03_scene','真实使用场景一：环境丰富、自然生活感，优先加入符合商品用途和目标受众的人物正在实际使用，展示明确的使用动作与商品价值'),
 ('04_scene','真实使用场景二：更换合理的空间、人物动作或用途，背景有生活细节；优先人物互动，不重复上一张布景'),
 ('05_material','材质细节：只描述已知主体和配件/内衬材质，局部特写与整体结合，不能混淆材质'),
 ('06_structure','结构展示：仅展示参考图及参数能证实的结构，不臆造折叠、拆装或承重功能'),
 ('07_details','重要细节和变体选择：真实细节特写，颜色/规格对比要清楚标注各选项，不暗示全部选项一起发货'),
 ('08_contents','套装实际内容：明确购买一个变体实际收到的件数、颜色和已知配件，不添加未声明配件'),
)

VISUAL_STYLE='视觉参考只借鉴构图、文字层级、留白和特写组织，不借用参考商品的外观、品牌或功能。采用真实商品摄影感，背景与品类/用途相符，优先柔和自然光和中性底色，商品与背景分离清楚；整组统一字体、圆角卡片、图标线条和留白。强调色少量取自实际商品或场景，不固定绿色，不改变变体真实颜色。俄文采用清晰粗体无衬线标题，通常1—2行，标题、卖点、补充说明形成三级层次，避免细小长段文字；手机缩略图中仍应能分清商品和标题。四周保留约5%安全边距，边框、尺寸箭头和文字不压住商品关键轮廓。无品牌商品不加品牌标、仿品牌椭圆徽章或PUREU字样；货号、SKU、任务编号、参考图文件名不得印进图内。'
MAIN_STYLE='【主图通用模板，仅作用于01主图，不改变02—08详情图的用途或设计要求】\n设计目标：手机缩略图先看清卖什么、商品真实样貌及最重要的购买理由；做一张完整俄语电商主图，不输出设计分析、候选版或额外海报。\n先根据本变体真实商品、用途、件数和已知卖点，只选择一种合适的构图：家具/家居用品用大主体搭配新设计的实际使用环境；小型配件/工具用放大的实物主体、简洁工作环境或摄影背景，配侧边信息；舒适体验/儿童用品可用自然人物实际使用，但人物不抢主体；多件套明确真实件数和商品单位，完整展示实际销售组合；技术类商品用清晰产品摄影和少量已知关键规格。不能把所有商品都放进同一种客厅或强行套统一信息栏。\n画面层级：先安排真实商品，主体视觉上占画面约三分之二，按形态灵活调整，完整保留关键轮廓、支架/腿脚及销售件数；再安排大标题和2—4条有事实依据的重要卖点，事实不足则减少。标题通常放上方或侧上方留白，约占画面高度15%—25%作为参考，不能为塞文字缩小、拉长或压扁商品。边缘留安全距离，信息卡不盖关键连接、功能部件和商品边界。\n标题样式：自然俄语，核心商品名称最大最醒目，修饰词次一级，优先1—2行；采用清晰粗体无衬线字体，整张最多两种协调字体，高对比配色，少量强调色与本品协调。长标题先删冗余形容词，不把文字缩成小字。缩略图仍能读出商品类别；不把内部货号、SKU、任务编号、文件名、广告口号堆进标题。\n卖点展现：按购买决策价值筛选，优先真实用途、可确认结构/材质、实际便利及明确关键规格；用2—4组简短词组搭配简洁图标、胶囊标签或少量信息卡，避免密集长段。仅将1—2个有依据且重要的数字放大，数字带准确单位；没有对应事实就不写。套装数量写清商品单位，场景里的桌子、床、杯子等道具不能被误认成随货套装。可选1—2个本品真实细节近景辅助说明，不能重复完整商品造成多件误判。\n原创场景：提供的风格样例只用于理解视觉层级、排版和信息组织；为当前商品重新设计适合其用途的空间、光线、镜头、配色和道具关系，不复刻样例的房间、家具组合、布景、人物姿势或机位。场景应有真实空间纵深、接触阴影和材质质感，陈设克制而有生活感，商品比背景更清楚。需要人物时，人物年龄/动作与真实用途相符，接触自然、比例正确，允许使用所必需的局部遮挡，但主体结构仍可辨认。没有适用依据，不用雪地、极端天气或特殊工况暗示性能。\n商品锁定与事实边界：只依照当前变体原始商品图和参数，优先保留实物抠图合成；准确保持外形、纹理、缝线、部件数量、支撑造型、颜色分区及件数，不从风格样例借用结构或功能。无品牌不加品牌/官方店标；不得搬用样例的承重、功率、节水率、适用年龄、质保、安全认证、抗过敏或护脊等宣称。道具不冒充赠品或配件，不增加未声明坐垫、装置、屏幕、图案或包装。生成前自检商品一致、文案有依据、字体易读、数量无误、场景原创；只交付当前约定的最终主图文件。'
MAIN_DETAIL_INFO='【主图选材规则】生成每个变体主图前，参考本组共用详情图及其原始资料中的可用信息，优先提取买家决策相关的真实材质、明确尺寸/规格、实际件数、支撑或连接结构和合理用途；按当前变体筛选2—4条最重要卖点，事实不足则减少。共用详情成图只作信息索引，不是新增事实来源：必须与用户提供的原始详情资料、本变体原图或已填参数相互核对，不能照抄AI生成的宣传词、数字或结构；无法确认就不采用。shared_information附件仅用于提取适用于当前变体且可核对的事实，不得作为主图商品外观或颜色依据。多变体差异只取当前所选变体，不能挪用其他颜色/尺寸/套装的专属信息；冲突时以当前变体已填参数与原图为准，不能判断就省略该条。主图仍只使用当前变体原始商品图保留外观，不复制详情图布景或把详情图拼成主图。'
EVIDENCE_STYLE='参考中的条绒、纽扣、旋转底座、泡沫按压和人物姿态均不是本商品事实：原商品是平绒就不能变成条绒，原图没有纽扣/扶手/旋转机构就不能增加。材质名称以已提供参数和本品原图为准，不能把вельвет与велюр混为一谈。旋转、透气、承重、护脊、久坐不累、长久不变形等宣传必须有明确事实依据；无法证实则不写。只有填充材料已明确时才可说明填充，不用通用泡沫切面图冒充实物内部，不凭渲染效果声称经过测试。人物按压只展示可确认的本品表面交互，不夸张改变坐垫厚度或形状。'
POSTER_RULE='不做把多张完整海报缩成一页的整套拼图或联系表；允许一张独立海报内使用局部特写、信息卡和尺寸标注，局部窗口仍是本张用途的辅助说明，不算额外交付图片。'
SEQUENTIAL_DELIVERY='【独立成品交付】按本任务编号输出独立3:4高清图片，每张至少750×1000。如对话已有整套视觉预览，各独立成品应沿用对应预览的商品、人物、背景、构图、文字和真实卖点；不能变成简化目录、替换背景或重新设计另一套。只有整套预览不算独立成品，必须实际生成并提供对应原图或真实下载入口，不只列文件名。不要输出额外预览/试稿，不编造链接；不把多张海报放到一个文件，不提供ZIP。'
DETAIL_STYLE='【共用详情视觉目标，仅用于商品位置02—08】\n制作可直接上架的摄影广告海报：大幅真实商品/人物使用照片铺满画面，醒目俄语大标题直接叠在照片留白处，少量大标签辅助阅读。每张只讲一个既定主题，保持7张原用途与顺序。目标是完整摄影大片，不是小商品图装进网页卡片、目录页、PPT、线稿或扁平插画房间。\n摄影执行：使用图像生成/编辑能力逐张完成真实照片级画面；程序只可辅助排版、尺寸与格式处理，不得用Python/PIL/SVG画家具、平涂房间、拼贴占位小图替代场景摄影。工具不可用或无法完成就明确说明，不提交简化模板冒充成图。商品可保留原图合成，但透视、尺度、环境光、接触阴影必须自然一致。\n构图优先级：商品真实性＞本张用途＞大幅摄影与可读标题＞辅助标签。先定实物/人物大构图，再安排文字。单件展示图商品通常占画面宽度65%—85%，主体完整；人物使用图让人物与商品共同构成约70%—85%的视觉主体，商品支撑结构仍可辨认。比例是构图指引，不能拉伸商品或截掉关键部件；材质/结构特写允许放大裁切局部。背景延伸到画面边缘，约5%安全边距只用于文字，不是四周白色相框；避免大面积空板、小主体和固定底部说明栏。\n标题与标签：自然俄语粗体无衬线大标题，1—2行，标题区域约15%—22%画面高度，字体显著大于标签；尺寸值、关键参数使用醒目数字和准确单位。最多2—3组简短大标签，尽量每组1—2行；圆角胶囊只承载少量文字，不把整张切成卡片网格。纹理近景要大到看清真实细节，不能做成邮票小窗。不加小栏目眉、长段说明、内部货号、SKU、任务编号、文件名；无品牌商品不加品牌标。事实不足时少写，不缩小字号塞满。\n原创布景与人物：重新设计适合本品的空间、机位、光线和陈设，不复刻示例的房间、桌椅组合、衣着或姿势。适合人物使用的家具等品类，两张场景图必须出现人物实际使用；一张呈现主要用途，另一张改变合理空间或主要动作，不能只换上一张背景色。不可让文字卡代替人物，也不强给无人使用的配件安排坐姿。真实皮肤、织物、金属反射与阴影。使用适度大景深，商品、人物与中后景家具陈设均清晰可辨；自然空间层次来自透视、光照和真实遮挡。不要浅景深、奶油散景、柔焦、移轴模糊、涂抹背景或虚化成色块，不用模糊背景隐藏不完整布景；材质特写只要求目标纹理与所指部件清楚，不强求微距所有平面同时合焦。避免塑料感人物与简化插画植物；其余图按主题展示商品/特写，不强加人物。配色协调本品，不固定绿色。\n事实边界：只用本组选项对应原图和已填参数。共同事实才写成全组选项通用，颜色/规格/件数差异分别标明；其他选项不能混装。没有清晰细节照片就不臆造纹理；不能据此虚构内部层数、剖面、机构或性能。数字不从效果样例复制，不自行加入1—3厘米误差。原始资料不足就省略该说明，保持本张用途和大幅实物摄影。'
LAYOUTS={'02_dimensions': '表现优化：一张大幅本品实景照片，完整商品占主体，上方超大尺寸主题标题；醒目尺寸数字和测量线准确对应真实测量位置。只标已知商品尺寸，不用包装尺寸，不由总高推算座高；未知不画。不要缩成居中的小商品配底部参数表。', '03_scene': '表现优化：第一实际使用场景。家具等适用品类必须有人物自然使用本品，商品与人物为大幅摄影主体；上方/侧方大标题，留白处2—3组大标签，场景丰富且真实。画出合理手部、接触与支撑，不用空房间加小商品图代替。', '04_scene': '表现优化：第二实际使用场景。适用品类必须有人物，空间或主要动作与前图明显不同，不复刻示例；商品仍清楚可辨。大幅实景摄影加大标题和少量真实用途标签，不用身体曲线/医疗符号暗示疗效。', '05_material': '表现优化：大幅可识别本品为主，结合2—3处足够大的真实纹理/材质近景，直接叠放短材质标签；不把主体缩小以给侧栏让位。主体、内衬、配件、填充分清，不混用вельвет与велюр，不用通用泡沫切块冒充实物内部。', '06_structure': '表现优化：大幅本品真实结构摄影配1—3处大特写，短引线准确解释连接和支撑；没有可确认拆解图就拍可见部位。无依据不画折叠、升降、旋转、气杆或内部剖面，不用线稿结构代替实物，不改成本图之外的填充宣传。', '07_details': '表现优化：真实重要细节与变体选择。大幅关键细节或本品为视觉锚点，辅以必要的对应原图选项及清晰颜色/规格标签；避免满屏等尺寸目录格子。只画有原图选项，未附原图仅写已知文字；说明购买时选择，不暗示所有颜色随货交付。', '08_contents': '表现优化：单个所选变体实际收到内容的大幅实物摄影，清楚具体商品单位、数量和已知配件；不同套装分别标注。简洁但真实的拍摄背景，避免卡片里的小商品；不把场景道具、未声明工具、赠品或重复近景算进件数。'}

def role_layout(name,brief):return brief+('；'+LAYOUTS[name] if name in LAYOUTS else '')

def generation_prompt(facts,group_facts='',expected=8):
 if expected not in (1,8):raise ValueError('图片交付数量只能为1或8')
 common='每张3:4竖版，自然俄语排版，风格统一。严格保持参考图对应变体的外形、颜色、比例和结构。不得虚构参数、认证、承重、防水或功能；卖点不足时减少文字，不编造补足。涉及人物时，人手、姿势、商品使用方式和尺寸比例应合理，人物与商品实际接触自然；允许真实坐姿等必要局部遮挡，但商品仍清楚可辨，关键轮廓、底座或支撑结构可见，不把主体大面积藏住。'
 if expected==1:
  contract='本任务只能生成和交付1张最终主图，不生成其他图片；文件名固定01_main.jpg。主图要求：'+ROLES[0][1]+'。后7张详情图由本地沿用首变体，不要重复生成。'
 else:
  contract='本任务只能交付8张最终独立图片，必须严格按01到08逐张生成并按该顺序交付；不要多出第9张，不提供额外封面、试稿、备选图或重复版本，不把整套海报拼成一张交付。需要修改时只将最终定稿纳入交付，不把过程图混入成品列表。固定顺序与用途：'+'；'.join(name+'.jpg：'+role_layout(name,brief) for name,brief in ROLES)+'。02—08为全组共用详情，涉及颜色或尺寸差异必须标注选项；无法兼容的细节不写成全组通用。'
 return SEQUENTIAL_DELIVERY+(DETAIL_STYLE if expected==8 else '')+contract+common+(VISUAL_STYLE if expected==1 else '')+EVIDENCE_STYLE+POSTER_RULE+MAIN_STYLE+MAIN_DETAIL_INFO+FIDELITY+'最终只列出本次'+str(expected)+'张对应编号的独立文件及逐张下载入口，文件数量必须与编号一一对应，不要打包，不提供ZIP。当前变体商品事实：'+facts+('。当前主图只依据本变体资料，其他变体不得作为外观依据：'+facts if expected==1 else '。同组全部变体资料：'+(group_facts or facts))

FIDELITY='商品一致性优先于设计美化：只能使用本次附件中该变体的原始商品参考图作为外观依据，禁止沿用历史对话、其他变体或AI生成图中的商品。优先保留原商品并抠图合成，只改背景和排版，不重新设计或替换成相似款。逐项保持真实轮廓、比例、表面纹理/缝线、靠背与座面形状、腿脚/支架数量和造型、扶手有无、连接结构及颜色分区；原图没有的扶手、脚轮、配件不得增加。参考图看不到的角度沿用可确认视角，不凭空补画隐藏结构。每套件数必须与当前变体参数一致。俄语标题与真实卖点放在留白区，不能为排版压缩或改变商品。'

def shared_prompt(group_facts):
 roles=ROLES[1:]
 return SEQUENTIAL_DELIVERY+DETAIL_STYLE+'本任务只重做全组共用的7张详情图，不生成主图、不改任何变体主图。严格交付7张独立3:4竖版JPG，文件按本任务01—07编号，分别对应商品详情位置02—08，不混入第8张或过程图，不把整套海报合成一张，不提供ZIP。用途顺序：'+'；'.join('%02d_%s.jpg：%s'%(i+1,name.split('_',1)[1],role_layout(name,brief)) for i,(name,brief) in enumerate(roles))+'。7张图各自的用途和顺序固定，视觉参考不能改变这些用途。统一自然俄语排版；人物互动重点用于原定的两张使用场景图，不把每一张都变成人物广告。涉及不同颜色、规格、材质或件数必须分别标注选项，不能混装或将不同结构写成全组通用。'+EVIDENCE_STYLE+POSTER_RULE+FIDELITY+'未附对应原图的变体只作已知参数的文字说明，不凭空绘制该选项的商品外观。最终仅提供这7个编号文件的逐张下载入口。全组事实：'+group_facts

def reference_contract(task):
 refs=task.get('references') or [];lines=[]
 for i,r in enumerate(refs):
  usage=('对应变体在共用详情中的真实商品外观' if r.get('purpose','variant_main')=='variant_main' else '全组共用细节依据，差异不可写成通用') if task.get('kind')=='shared_details' else ('仅用于本变体主图外观' if r.get('purpose','variant_main')=='variant_main' else '用于主图筛选并核对可用卖点/材质/重要参数，不作为本变体外观依据')
  lines.append(str(i+1)+'：'+str(r.get('name','原图'))+'；货号 '+str(r.get('sku') or task.get('sku',''))+'；用途 '+usage)
 return FIDELITY+'\n本次附件对应关系：\n'+'\n'.join(lines)


def main_detail_references(task,tasks):
 """Original shared detail sources, information only; never another variant's hero."""
 leader=task.get('copy_leader') or task['sku']
 source=next((t for t in tasks if t.get('sku')==leader and t.get('state')!='cancelled'),task)
 own=[r for r in task.get('references',[]) if r.get('purpose')!='shared_information']
 shared=source.get('detail_references') or [r for r in source.get('references',[]) if r.get('purpose') in ('shared_gallery','shared_detail')]
 seen={r.get('path') for r in own}
 return own+[dict(r,purpose='shared_information',sku=source['sku']) for r in shared if r.get('path') not in seen]


def sheet_prompt(facts,group_facts='',expected=8,shared=False):
 from contact_sheet import contract
 if shared:
  roles=ROLES[1:];style=DETAIL_STYLE
 else:
  roles=ROLES if expected==8 else ROLES[:1];style=DETAIL_STYLE+MAIN_STYLE+MAIN_DETAIL_INFO
 if expected==1:return generation_prompt(facts,group_facts,1)
 # Assemble only the sheet contract; never append conflicting independent-file rules.
 return contract(expected)+style+EVIDENCE_STYLE+FIDELITY+'各格用途顺序：'+'；'.join(str(i+1)+'：'+role_layout(n,b) for i,(n,b) in enumerate(roles))+'。当前变体事实：'+facts+'。全组选项事实：'+(group_facts or facts)
